function entityTableStepHtml(step){return '<section class="entity-step-pane '+(step===2?'active':'')+'" data-entity-step-pane="2"><div class="entity-form-card"><div class="entity-section-title"><b>选择映射表</b><small>可选择一张或多张项目内已授权数据表作为实体数据来源</small></div><div class="entity-table-picker"><aside><div class="searchbox"><input placeholder="搜索数据源、库或表"><svg class="ico"><use href="#search"/></svg></div><h4>项目数据资源</h4><button>▾ 客户运营库 <small>MySQL</small></button><button class="selected">　✓ customer_master</button><button>　□ customer_contact</button><button>▾ 交易分析库 <small>Oracle</small></button><button class="selected">　✓ order_summary</button><button>　□ payment_detail</button></aside><main><header><b>已选择数据表</b><span>2 张表 · 支持拖拽调整主从关系</span></header><article><i>主</i><div><b>customer_master</b><small>客户运营库 / CRM · 32 个字段 · 1,286,420 行</small></div><em>主表</em><button>×</button></article><article><i class="join">联</i><div><b>order_summary</b><small>交易分析库 / DWD · 18 个字段 · 9,825,610 行</small></div><em>LEFT JOIN · customer_id</em><button>×</button></article><div class="entity-join-hint"><b>关联条件</b><code>customer_master.customer_id = order_summary.customer_id</code><button>编辑关联</button></div></main></div></div></section>'}
