function setEntityStep(step){
 step=Math.max(1,Math.min(4,Number(step)||1));
 var designer=document.querySelector('.entity-designer');
 if(!designer)return;
 designer.dataset.entityCurrentStep=step;
 designer.querySelectorAll('[data-entity-step-target]').forEach(function(x){var n=Number(x.dataset.entityStepTarget);x.classList.toggle('active',n===step);x.classList.toggle('done',n<=step)});
 designer.querySelectorAll('[data-entity-step-pane]').forEach(function(x){x.classList.toggle('active',Number(x.dataset.entityStepPane)===step)});
 var prev=designer.querySelector('[data-entity-prev]'),next=designer.querySelector('[data-entity-next]');
 if(prev)prev.style.visibility=step===1?'hidden':'visible';
 if(next)next.textContent=step===4?'保存配置':'保存并下一步';
 try{var url=new URL(location.href);url.searchParams.set('entityView','edit');url.searchParams.set('step',step===1?'basic':step===2?'tables':step===3?'properties':'mapping');history.replaceState(null,'',url)}catch(e){}
 if(step===4){
  var roadmap=new URLSearchParams(location.search).get('roadmap');
  entityMappingMode=roadmap==='entity-virtual-mapping'?'virtual':'physical';
  designer.querySelectorAll('[data-entity-mode]').forEach(function(x){x.classList.toggle('active',x.dataset.entityMode===entityMappingMode)});
  var detail=document.getElementById('entityModeDetail');
  if(detail)detail.innerHTML=entityMappingMode==='virtual'?'<b>虚拟映射查询策略</b><p>数据保留在外部数据源；平台根据字段映射下推查询并实时返回结果，不产生数据副本。</p><label>访问方式<select><option>查询下推 + 结果缓存</option><option>仅实时查询</option></select></label>':'<b>物理映射执行策略</b><p>首次全量同步，之后每 30 分钟增量同步；发布后卡片展示同步进度。</p><label>同步方式<select><option>全量 + 增量 CDC</option><option>仅定时全量</option></select></label>';
 }
}
