function aigoResourcePickerHtml(){return '<div class="aigo2-mask" id="aigoResourceMask"><section class="aigo2-resource-modal"><header><div><h2>从项目资源选择</h2><p>仅展示当前项目已申请且有权使用的资源</p></div><button data-aigo-resource-close>×</button></header><div class="aigo2-resource-tabs"><button class="active" data-aigo-resource-type="doc">项目文档 <span>8</span></button><button data-aigo-resource-type="table">数据表 <span>5</span></button><div class="searchbox"><svg class="ico"><use href="#search"/></svg><input placeholder="搜索资源名称或来源"></div></div><div class="aigo2-resource-picker-view active" data-aigo-resource-view="doc">'+[['质量追溯与供应风险分析方案.docx','客户运营部','DOCX · 已解析 · 38 页'],['供应商质量管理制度.pdf','质量管理部','PDF · 已解析 · 26 页'],['采购业务流程与风险控制.docx','采购管理部','DOCX · 已解析 · 42 页'],['产线异常处置手册.pdf','生产制造域','PDF · 已解析 · 31 页']].map(function(x,i){return '<label><input type="checkbox" '+(i<2?'checked':'')+'><i class="doc">文</i><span><b>'+x[0]+'</b><small>'+x[1]+' · '+x[2]+'</small></span><em>项目资源</em></label>'}).join('')+'</div><div class="aigo2-resource-picker-view" data-aigo-resource-view="table">'+[['dwd_supplier_quality_event','CRM_PROD / quality','28 个字段 · 2.4M 条'],['ods_purchase_batch','ERP_PROD / purchase','35 个字段 · 8.9M 条'],['dim_supplier_master','MDM / supplier','46 个字段 · 36K 条'],['dwd_product_lot_trace','DWD / quality','31 个字段 · 12.6M 条']].map(function(x,i){return '<label><input type="checkbox" '+(i<2?'checked':'')+'><i class="table">表</i><span><b>'+x[0]+'</b><small>'+x[1]+' · '+x[2]+'</small></span><em>已授权</em></label>'}).join('')+'</div><footer><span>已选择 <b id="aigoResourceCount">2</b> 项</span><button class="btn" data-aigo-resource-close>取消</button><button class="btn primary" id="aigoConfirmResources">确认选择</button></footer></section></div>'}
function aigoReviewHtml(roadmap){return '<div class="aigo2-mask" id="aigoReviewMask"><section class="aigo2-review-modal"><header><div><span>INCREMENTAL MERGE REVIEW</span><h2>增量构建与融合确认</h2><p>所有决策将写入变更集，可在发布前撤销或重新分析。</p></div><button data-aigo-review-close>×</button></header><nav class="aigo2-review-steps">'+[['1','复用确认'],['2','新增与扩展'],['3','冲突处理'],['4','变更预览']].map(function(x,i){return '<button class="'+(i===0?'active':'')+'" data-aigo-review-step="'+x[0]+'"><i>'+x[0]+'</i><span>'+x[1]+'</span></button>'}).join('<em>→</em>')+'</nav><div class="aigo2-review-body"><section class="aigo2-review-pane active" data-aigo-review-pane="1"><div class="aigo2-review-intro"><b>确认可复用的已有本体元素</b><p>复用可以保持跨场景语义一致；可选择仅引用、扩展属性或新建独立对象。</p></div><article class="aigo2-merge-item"><label><input type="checkbox" checked><i>复</i><span><b>候选“供应商” → 已有“合作伙伴”</b><small>名称相似度 82% · 描述相似度 94% · 共享 5 个属性</small></span></label><div class="aigo2-compare"><span><b>候选</b>供应商名称、信用等级、质量等级、供货范围</span><em>→</em><span><b>已有</b>伙伴名称、合作等级、服务范围、状态</span></div><div class="aigo2-decision-buttons"><button class="active" data-aigo-decision>复用并扩展</button><button data-aigo-decision>仅引用</button><button data-aigo-decision>仍然新建</button></div></article><article class="aigo2-merge-item"><label><input type="checkbox" checked><i>复</i><span><b>候选“责任人” → 已有“人员”</b><small>语义相似度 97% · 属性完全覆盖</small></span></label><div class="aigo2-decision-buttons"><button class="active" data-aigo-decision>直接复用</button><button data-aigo-decision>新建业务角色</button></div></article></section><section class="aigo2-review-pane" data-aigo-review-pane="2"><div class="aigo2-review-intro"><b>确认新增对象、属性和关系</b><p>可以逐项取消、修改 API 标识或调整映射来源。</p></div>'+[['采购批次','新增对象','6 属性 · 映射 ods_purchase_batch'],['质量异常','新增对象','4 属性 · 来源业务文档'],['产品批次.质量等级','新增属性','映射 quality_grade'],['供应商提供采购批次','新增关系','多对多 · 可追溯']].map(function(x){return '<article class="aigo2-review-row"><input type="checkbox" checked><i>＋</i><span><b>'+x[0]+'</b><small>'+x[2]+'</small></span><em>'+x[1]+'</em><button>编辑</button></article>'}).join('')+'</section><section class="aigo2-review-pane" data-aigo-review-pane="3"><div class="aigo2-review-intro warn"><b>处理 1 项语义冲突</b><p>系统不会自动覆盖已有定义，请明确选择本次融合策略。</p></div><article class="aigo2-conflict-card"><header><i>!</i><span><b>“供应商”与“合作伙伴”的概念边界</b><small>已有合作伙伴包括渠道、服务和供货伙伴；新材料中的供应商仅指供货主体。</small></span></header><div class="aigo2-conflict-options"><button class="active" data-aigo-decision><i>推荐</i><b>复用合作伙伴</b><small>新增 partner_type=供应商，并扩展质量相关属性</small></button><button data-aigo-decision><b>新建供应商子类</b><small>建立 Supplier → Partner 继承关系</small></button><button data-aigo-decision><b>新建独立对象</b><small>不与现有概念建立复用关系</small></button></div><label>决策说明<textarea>供应商是合作伙伴的一种业务角色，优先保持统一主体模型，并扩展质量管理属性。</textarea></label></article></section><section class="aigo2-review-pane" data-aigo-review-pane="4"><div class="aigo2-review-intro"><b>变更集预览</b><p>确认后生成草稿版本 V3.7，不会直接覆盖当前已发布版本。</p></div><div class="aigo2-final-summary"><span><i>＋</i><b>3</b><small>新增对象</small></span><span><i>关</i><b>3</b><small>新增关系</small></span><span><i>属</i><b>9</b><small>属性变更</small></span><span><i>复</i><b>2</b><small>复用对象</small></span></div><div class="aigo2-version-card"><span><i>V</i><b>客户经营本体 V3.7（草稿）</b><small>基于 V3.6 · 变更集 INC-20260922-018 · 可回滚</small></span><button>查看完整差异</button></div><label class="aigo2-validation"><input type="checkbox" checked><span><b>生成后执行映射与一致性校验</b><small>验证数据表字段映射、关系基数、API 标识及循环依赖</small></span></label></section></div><footer><span id="aigoReviewHint">第 1/4 步 · 2 项复用建议待确认</span><button class="btn" data-aigo-review-close>稍后处理</button><button class="btn" id="aigoReviewPrev" disabled>上一步</button><button class="btn primary" id="aigoReviewNext">确认并继续</button></footer></section></div>'}
