function resourceRequestHtml(){var roadmapKey=new URLSearchParams(location.search).get('roadmap'),roadmap=roadmapKey==='project-resource-approval'||roadmapKey==='ontology-project-resource',ontologyRoadmap=roadmapKey==='ontology-project-resource',tabs=[['all','全部'],['doc','文档'],['data','数据表'],['ontology','本体'],['kb','知识库'],['action','Action']];return '<div class="pr-page '+(roadmap?'roadmap-target':'')+'">'+(roadmap?'<section class="pr-roadmap-note"><span>'+(ontologyRoadmap?'10 月上线':'9 月上线')+'</span><div><b>'+(ontologyRoadmap?'项目资源申请与发布':'项目资源申请与审批')+'</b><p>'+(ontologyRoadmap?'从项目所在空间及子空间申请文档、数据表、本体、知识库等资源；审批通过后进入项目资源列表，项目产出可按空间规则申请发布。':'从项目所在空间及子空间申请各类资源，提交前展示空间审批链。')+'</p></div><button type="button" data-project-roadmap-close aria-label="关闭说明">×</button></section>':'')+'<div class="pr-head"><div><h1>项目资源</h1><p>统一管理已授权、项目自建与申请中的全类型资源 · '+projectName()+'</p></div><button class="btn primary '+(ontologyRoadmap?'roadmap-target-highlight':'')+'" id="openProjectResourceRequest">＋ 申请空间资源</button></div><div class="pr-summary"><span><i>全</i><div><b id="prCountAll">5</b><small>全部资源</small></div></span><span><i class="doc">文</i><div><b id="prCountDoc">2</b><small>文档</small></div></span><span><i class="data">表</i><div><b id="prCountData">1</b><small>数据表</small></div></span><span><i class="ontology">本</i><div><b id="prCountOntology">1</b><small>本体</small></div></span><span><i class="kb">知</i><div><b id="prCountKb">1</b><small>知识库</small></div></span></div><section class="pr-panel"><div class="pr-toolbar"><div class="pr-type-tabs">'+tabs.map(function(x){return '<button class="'+(x[0]===prState.type?'active':'')+'" data-pr-type="'+x[0]+'">'+x[1]+'</button>'}).join('')+'</div><div class="searchbox"><svg class="ico"><use href="#search"/></svg><input id="prResourceSearch" placeholder="搜索项目资源"></div></div><div class="pr-table-head"><span>资源</span><span>类型</span><span>来源</span><span>项目权限</span><span>状态</span><span>操作</span></div><div id="prResourceRows"></div><div class="pr-footer"><span>已申请资源审批通过后自动加入本列表</span><div class="pr-pager"><button>‹</button><button class="active">1</button><button>2</button><button>›</button></div></div></section>'+prRequestModalHtml()+'</div>'}
function prRequestModalHtml(){return '<div class="pr-request-mask" id="prRequestMask"><div class="pr-request-modal"><header class="pr-request-head"><div><h2>申请项目资源</h2><p>'+projectName()+' · 可从项目所在空间及全部子空间申请</p></div><button data-pr-close>×</button></header><div class="pr-request-body" id="prRequestForm"><div class="pr-request-note"><b>申请范围</b><span>可跨空间、跨类型多选；审批通过后自动加入项目资源列表。</span></div><div class="pr-request-layout"><aside class="pr-space-tree"><div class="searchbox"><svg class="ico"><use href="#search"/></svg><input id="prSpaceSearch" placeholder="搜索空间"></div><div id="prSpaceRows"></div></aside><section class="pr-picker"><div class="pr-picker-head"><span><b id="prPickSpace">客户运营部</b><small>项目所在空间</small></span><select id="prPickType"><option value="all">全部类型</option><option value="doc">文档</option><option value="data">数据表</option><option value="ontology">本体</option><option value="kb">知识库</option><option value="action">Action</option></select><div class="searchbox"><svg class="ico"><use href="#search"/></svg><input id="prPickSearch" placeholder="搜索名称或来源"></div></div><div class="pr-pick-list" id="prPickList"></div><div class="pr-picked-bar"><span>已选择 <b id="prSelectedCount">0</b> 项资源</span><span class="spacer"></span><button class="mini" id="prClearSelection">清空选择</button></div></section></div><div class="pr-approval-preview"><header><b>审批链路</b><span id="prApprovalScope">按客户运营部的资源申请规则</span></header><div class="pr-chain"><span><i>1</i>陈宇 · 提交</span><em>→</em><span class="active"><i>2</i><b id="prApprover">客户运营部管理员审批</b></span><em>→</em><span><i>3</i>项目管理员确认</span><em>→</em><span><i>4</i>资源加入项目</span></div></div><div class="pr-request-reason"><label>申请说明</label><textarea id="prReason">用于当前项目的本体构建、知识检索与业务分析。</textarea></div></div><div class="pr-result" id="prResult"><i>✓</i><h3>资源申请已提交</h3><p id="prResultText">申请中的资源已加入项目资源列表，状态为“待审批”。</p><div class="pr-chain"><span><i>✓</i>已提交</span><em>→</em><span class="active"><i>2</i>空间管理员审批</span><em>→</em><span><i>3</i>加入项目</span></div></div><footer class="pr-request-foot"><span id="prFootHint">同一批资源将按所属空间拆分为审批单</span><span class="spacer"></span><button class="btn" data-pr-close>取消</button><button class="btn primary" id="prSubmit">提交资源申请</button></footer></div></div>'}
function renderPrResources(){var box=document.getElementById('prResourceRows');if(!box)return;var q=prState.query.toLowerCase(),items=prState.resources.filter(function(x){return(prState.type==='all'||x.type===prState.type)&&(!q||x.name.toLowerCase().indexOf(q)>-1||x.source.toLowerCase().indexOf(q)>-1)});box.innerHTML=items.map(function(x){return '<article class="pr-row"><div class="pr-resource-name"><i class="pr-resource-icon '+x.type+'">'+prIcon(x.type)+'</i><span><b>'+x.name+'</b><small>'+x.updated+'</small></span></div><span>'+x.label+'</span><span class="pr-source">'+x.source+'</span><span class="pr-permission">'+x.permission+'</span><span class="pr-status '+(x.status==='待审批'?'pending':'')+'">'+x.status+'</span><button class="mini">'+(x.status==='待审批'?'查看审批':'查看')+'</button></article>'}).join('')||'<div class="pr-empty">暂无符合条件的项目资源</div>';document.getElementById('prCountAll').textContent=prState.resources.length;['doc','data','ontology','kb'].forEach(function(t){var el=document.getElementById('prCount'+t.charAt(0).toUpperCase()+t.slice(1));if(el)el.textContent=prState.resources.filter(function(x){return x.type===t}).length})}
function prSpaces(){return['客户运营部','客户运营部 / 洞察研究组','客户运营部 / 数据分析组','客户运营部 / 体验设计组','客户运营部 / 服务体验组']}
function renderPrSpaces(){var box=document.getElementById('prSpaceRows');if(!box)return;box.innerHTML=prSpaces().map(function(s,i){return '<button class="pr-space-row '+(i?'child ':'')+(s===prState.space?'active':'')+'" data-pr-space="'+s+'"><i>'+(i?'子':'空')+'</i>'+s.split(' / ').pop()+(i?'':'<em>项目所在空间</em>')+'</button>'}).join('')}
function renderPrPicker(){var box=document.getElementById('prPickList');if(!box)return;var type=document.getElementById('prPickType').value,q=document.getElementById('prPickSearch').value.trim().toLowerCase(),items=prCatalog.filter(function(x){return x.space.indexOf(prState.space)===0&&(type==='all'||x.type===type)&&(!q||x.name.toLowerCase().indexOf(q)>-1||x.space.toLowerCase().indexOf(q)>-1)});box.innerHTML=items.map(function(x){var checked=prState.selected.indexOf(x.id)>-1?' checked':'';return '<label class="pr-pick-row"><input type="checkbox" data-pr-pick="'+x.id+'"'+checked+'><span><b>'+x.name+'</b><small>'+x.space+'</small></span><em>'+x.label+'</em><span class="pr-status">可申请</span></label>'}).join('')||'<div class="pr-empty">当前空间无符合条件的可申请资源</div>';document.getElementById('prSelectedCount').textContent=prState.selected.length;document.getElementById('prPickSpace').textContent=prState.space.split(' / ').pop();document.getElementById('prApprover').textContent=prState.space.split(' / ').pop()+'管理员审批';document.getElementById('prApprovalScope').textContent='按'+prState.space.split(' / ').pop()+'的资源申请规则'}
function openPrRequest(){prState.selected=[];prState.space=prSpaces()[0];document.getElementById('prRequestMask').classList.add('open');document.getElementById('prRequestForm').style.display='block';document.getElementById('prResult').classList.remove('show');document.getElementById('prSubmit').style.display='inline-flex';document.getElementById('prFootHint').textContent='同一批资源将按所属空间拆分为审批单';renderPrSpaces();renderPrPicker()}
var activeModule='aigo',omTagTargetCard=null,aigoEntryParams=new URLSearchParams(location.search),aigoEntryChoicePending=aigoEntryParams.get('entry')==='project'||!aigoEntryParams.has('module')||aigoEntryParams.get('module')==='aigo';
var aigoStartPreferenceKey='knora:ontologyStartPreference';
