function aigoMergedBuilderHtml(showChoice){return '<div class="aigo-merged-page"><header class="aigo-merged-head"><div><span>AIGO · 项目默认入口</span><h1>本体自动构建</h1><p>根据对话引导自动识别业务要素并构建本体；也可以跳过引导，直接进入左侧菜单手动构建。</p></div><div class="aigo-merged-actions"><button class="btn" type="button" data-aigo-manual-start>直接手动构建</button><button class="btn primary" type="button" data-aigo-guide-start>按照引导自动构建</button></div></header><section class="aigo-original-notice"><i>AI</i><div><b>已完整载入 AIGO 本体自动构建原型</b><p>下方保留原型中的全部流程与交互。您可以随时使用左侧菜单切换到手动构建，返回本页后继续引导。</p></div><button type="button" data-aigo-choice-open>重新选择构建方式</button></section><div class="aigo-original-frame"><iframe id="aigoOriginalFrame" title="AIGO 本体自动构建" src="ontology-aigo-original.html"></iframe></div><div class="aigo-start-choice'+(showChoice?' open':'')+'" id="aigoStartChoice" role="dialog" aria-modal="true" aria-labelledby="aigoStartTitle"><section><button class="aigo-choice-close" type="button" data-aigo-guide-start aria-label="关闭">×</button><span class="aigo-choice-mark">AI</span><h2 id="aigoStartTitle">选择本体构建方式</h2><p>可以让 AIGO 通过对话逐步引导，也可以直接进入项目菜单手动配置；两种方式可随时切换。</p><div class="aigo-choice-grid"><button type="button" class="recommended" data-aigo-guide-start><i>✦</i><span><b>根据引导自动构建</b><small>通过业务描述、文档和数据表，自动识别对象、关系、规则及其它要素</small><em>推荐</em></span></button><button type="button" data-aigo-manual-start><i>⌘</i><span><b>直接手动构建</b><small>从业务对象开始，按左侧四大分组逐项进行配置</small></span></button></div><div class="aigo-choice-remember"><label><input type="checkbox" id="aigoSkipReminder"><span>不再提醒</span></label><button type="button" data-aigo-choice-help aria-label="查看不再提醒说明">?</button><small id="aigoChoiceHelp">原型演示中会始终保留此提示；产品实现时，勾选后将按本次选择默认进入自动或手动构建页面。</small></div></section></div></div>'}
function projectSemanticGraphHtml(){return '<div class="project-graph-page"><header class="om-head"><div class="om-title"><h1>语义图谱</h1><p>从当前项目全局视角查看业务对象、关联、事实、规则与行为之间的语义网络。</p><span class="om-project-scope">当前项目 · '+projectName()+'</span></div><div class="spacer"></div><select class="select"><option>全部业务域</option><option>客户域</option><option>营销域</option><option>服务域</option></select><div class="searchbox"><svg class="ico"><use href="#search"/></svg><input placeholder="搜索对象、关系或规则"></div></header><section class="project-graph-summary"><article><i>对</i><span><b>28</b><small>业务对象</small></span></article><article><i>关</i><span><b>42</b><small>业务关联</small></span></article><article><i>事</i><span><b>16</b><small>事实明细</small></span></article><article><i>规</i><span><b>21</b><small>规则与行为</small></span></article></section><div class="project-graph-layout"><section class="project-graph-canvas"><header><b>'+projectName()+' · 全局语义图谱</b><small>仅展示当前项目内已发布与草稿中的语义要素</small><nav><button class="active">关系视图</button><button>层级视图</button><button>适应画布</button></nav></header><div class="project-graph-board"><svg viewBox="0 0 900 520" preserveAspectRatio="none"><path d="M165 95 C300 130 355 205 455 255"/><path d="M735 100 C620 135 560 210 455 255"/><path d="M170 425 C300 390 345 300 455 255"/><path d="M735 425 C615 385 560 300 455 255"/><path d="M455 80 C455 145 455 190 455 255"/><path d="M455 255 C455 330 455 390 455 470"/></svg><article class="project-graph-node center"><i>核</i><b>客户主体</b><small>核心业务对象 · 28 个属性</small></article><article class="project-graph-node n1"><i>对</i><b>产品目录</b><small>业务对象</small></article><article class="project-graph-node n2"><i>关</i><b>客户购买产品</b><small>业务关联</small></article><article class="project-graph-node n3"><i>事</i><b>订单支付事实</b><small>事实明细</small></article><article class="project-graph-node n4"><i>规</i><b>高价值客户判定</b><small>业务规则</small></article><article class="project-graph-node n5"><i>行</i><b>更新客户等级</b><small>业务操作与行为</small></article><article class="project-graph-node n6"><i>流</i><b>客户流失干预流程</b><small>业务流程</small></article></div></section><aside class="project-graph-side"><header><b>图谱信息</b></header><section><h3>要素图例</h3><div class="project-graph-legend"><span><i></i>业务对象与属性</span><span><i></i>业务关联与事实</span><span><i></i>规则、行为与流程</span></div></section><section><h3>项目覆盖</h3><div class="project-graph-legend"><span><b>6</b> 个业务域</span><span><b>107</b> 个语义要素</span><span><b>86%</b> 已完成数据映射</span></div></section><section><h3>最近变化</h3><div class="project-graph-change"><article><b>新增“客户风险等级”属性</b><small>陈宇 · 10 分钟前</small></article><article><b>发布“客户流失干预流程”</b><small>赵敏 · 今天 09:42</small></article><article><b>更新客户与订单关系</b><small>系统自动构建 · 昨天</small></article></div></section></aside></div></div>'}
